out = {k: {"summary": v} for k, v in S.items()}
path = r"D:\رسانامه تکمیلی\sql\llm\summaries_llm_03.json"
with open(path, "w", encoding="utf-8") as f:
    json.dump(out, f, ensure_ascii=False, indent=2)

with open(path, encoding="utf-8") as f:
    d = json.load(f)
assert len(d) == 24, f"count={len(d)}"
empty = [k for k, v in d.items() if not v.get("summary", "").strip()]
assert not empty, f"empty: {empty}"
over = [k for k, v in d.items() if len(v["summary"]) > 240]
assert not over, f"over 240: {over}"
print("OK keys:", len(d), "| all non-empty | all <= 240 chars")
for k, v in d.items():
    print(f"{k}  chars={len(v['summary'])}")
